import{bt as e,ct as t,lt as n,n as r,ot as i,rt as a,st as o,wt as s}from"./chunks/framework.CcbqhlXh.js";var c=JSON.parse(`{"title":"Troubleshooting Types","description":"","frontmatter":{},"headers":[],"relativePath":"ts/troubleshooting-types.md","filePath":"ts/troubleshooting-types.md","lastUpdated":1792041788000}`),l={name:`ts/troubleshooting-types.md`};function u(r,c,l,u,d,f){let p=s(`CopyOrDownloadAsMarkdownButtons`);return e(),i(`div`,null,[c[0]||=a(`h1`,{id:`troubleshooting-types`,tabindex:`-1`},[t(`Troubleshooting Types `),a(`a`,{class:`header-anchor`,href:`#troubleshooting-types`,"aria-label":`Permalink to “Troubleshooting Types”`},`​`)],-1),n(p),c[1]||=o(`<p>This page covers two problems with types: a <code>@tolki/*</code> type that resolves to <code>any</code>, and an API resource macro that publishes <code>unknown</code>.</p><h2 id="a-tolki-type-resolves-to-any" tabindex="-1">A <code>@tolki/*</code> Type Resolves to <code>any</code> <a class="header-anchor" href="#a-tolki-type-resolves-to-any" aria-label="Permalink to “A @tolki/* Type Resolves to any”">​</a></h2><p>A type you import from a <code>@tolki/*</code> package can resolve to <code>any</code> in your app, with no editor warning and no build error. If it does, you&#39;re likely on a version whose declaration files break once installed from npm. This section shows how to confirm it and which versions fix it.</p><h3 id="symptom" tabindex="-1">Symptom <a class="header-anchor" href="#symptom" aria-label="Permalink to “Symptom”">​</a></h3><p>An import from <code>@tolki/ts</code>, <code>@tolki/enum</code>, or <code>@tolki/utils</code> resolves to <code>any</code> instead of its real type, and neither <code>tsc</code> nor your editor reports anything wrong.</p><p>It stays silent because of <code>skipLibCheck: true</code>, the default in most starter <code>tsconfig.json</code> files. That option skips type checking inside <code>.d.ts</code> files, including the import line that fails to resolve. The import becomes <code>any</code> instead of raising <code>TS2307: Cannot find module</code>.</p><h3 id="checking-your-project" tabindex="-1">Checking Your Project <a class="header-anchor" href="#checking-your-project" aria-label="Permalink to “Checking Your Project”">​</a></h3><p>Paste this into your project, replacing <code>EnumConst</code> and the package with a <code>@tolki/*</code> type you already import:</p><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { EnumConst } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@tolki/ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ShouldBeAType</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;not-a-function&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> probe</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ShouldBeAType</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {} </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> EnumConst</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>If this compiles without an error, the type resolved to <code>any</code>, and you&#39;re affected. <code>any</code> is assignable to anything, including a type it isn&#39;t. If <code>tsc</code> reports <code>TS2322</code> (<code>EnumConst</code> is not assignable to <code>&quot;not-a-function&quot;</code>), the type resolves correctly.</p><h3 id="cause" tabindex="-1">Cause <a class="header-anchor" href="#cause" aria-label="Permalink to “Cause”">​</a></h3><p>The affected versions ship declaration files that import types from another <code>@tolki/*</code> package through a relative path into the Tolki source repository, instead of through the package name. That path doesn&#39;t exist in your <code>node_modules</code>, so the import resolves nowhere.</p><p>You can spot it in the package&#39;s <code>.d.ts</code> files. An affected version has an import like this one:</p><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// Affected: a relative path that exists only in the Tolki source repository</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { AsEnum, DefineEnumResult } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;../packages/types/src/index.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>A fixed version imports through the package name:</p><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// Fixed: the package name, resolved through node_modules</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { AsEnum, DefineEnumResult } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@tolki/types&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>The runtime JavaScript was never affected. Only the <code>.d.ts</code> files were.</p><h3 id="fix" tabindex="-1">Fix <a class="header-anchor" href="#fix" aria-label="Permalink to “Fix”">​</a></h3><p>Upgrade each <code>@tolki/*</code> package you use to at least the version that fixed its declaration files:</p><div class="table-scroll"><table tabindex="0"><thead><tr><th>Package</th><th>Fixed in</th></tr></thead><tbody><tr><td><code>@tolki/ts</code></td><td><code>1.0.2</code></td></tr><tr><td><code>@tolki/enum</code></td><td><code>1.1.2</code></td></tr><tr><td><code>@tolki/utils</code></td><td><code>1.2.0</code></td></tr></tbody></table></div><p>For example, upgrade <code>@tolki/ts</code> with your package manager:</p><div class="vp-code-group"><div class="tabs"><input type="radio" name="group-96" id="tab-97" checked><label data-title="npm" for="tab-97">npm</label><input type="radio" name="group-96" id="tab-98"><label data-title="yarn" for="tab-98">yarn</label><input type="radio" name="group-96" id="tab-99"><label data-title="pnpm" for="tab-99">pnpm</label></div><div class="blocks"><div class="language-bash active" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tolki/ts@latest</span></span></code></pre></div><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tolki/ts@latest</span></span></code></pre></div><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tolki/ts@latest</span></span></code></pre></div></div></div><p>Then run the check in <a href="#checking-your-project">Checking Your Project</a> again. It should now report <code>TS2322</code>.</p><h2 id="a-resource-macro-publishes-unknown" tabindex="-1">A Resource Macro Publishes <code>unknown</code> <a class="header-anchor" href="#a-resource-macro-publishes-unknown" aria-label="Permalink to “A Resource Macro Publishes unknown”">​</a></h2><p>A key that calls a macro you registered on <code>JsonResource</code>, such as <code>&#39;label&#39; =&gt; $this-&gt;label()</code>, can publish <code>unknown</code>. The package types a macro from its native return type, then its <code>@return</code> docblock, then its body. It reads the body without the values the call passes, and it doesn&#39;t read the body of a closure declared outside a class method, such as in <code>bootstrap/app.php</code>.</p><p>Give the closure a return type, and the key takes it:</p><div class="language-php" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">JsonResource</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">macro</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;label&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ()</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> strtoupper</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$this</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">resource</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">title);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>A <code>@return</code> docblock on the closure works too, but only when you declare the closure inside a class, such as in a service provider&#39;s <code>boot()</code> method.</p><p>If the key publishes the type of a model method with the same name instead, the package didn&#39;t see the macro. Register it in the <code>boot()</code> method of a provider that isn&#39;t deferred, so it exists before <code>ts:publish</code> reads your resources. See <a href="./api-resources.html#resource-macros">Resource Macros</a>.</p>`,29)])}var d=r(l,[[`render`,u]]);export{c as __pageData,d as default};